 p=OUT/f"question-social-content-hist-ic-iv-1-{i}.json";d=json.loads(p.read_text(encoding="utf-8"));assert d["lessonId"]==LESSON and d["knowledgeIds"]==[KG];old=d["answer"]["value"];oi=ord(old)-65;correct=d["options"][oi]["text"];rest=[x["text"] for j,x in enumerate(d["options"]) if j!=oi];ti=ord(target)-65;ordered=rest[:ti]+[correct]+rest[ti:];d["options"]=[{"id":chr(65+j),"text":x}for j,x in enumerate(ordered)];focus,reason=FOCI[i-1]
 d["answer"]={"value":target,"explanation":f"本題聚焦「{focus}」。{reason} 正確答案為選項 {target}：「{correct}」。"};d["solutionStrategy"]=f"先定位{focus}的空間、群體、制度與資料，再分開城市設計、實際使用和資源差異；{reason}"
