 d["examPatternRefs"]=refs();d["updatedAt"]="2026-09-13";d["reviewStatus"]="draft";d["provenance"]["authoringNote"]="依官方課綱、歷 Ic-Ⅳ-1 知識圖譜及三所公立學校公開社會科試題的城市變遷、資料判讀與多方角色能力方向獨立改寫；未複製原題文字、選項、圖片或答案，待逐題學科與 Terra 複核。";p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
